// Build-time input for the landing's "Popular used EVs" section (T-131, Decision 038).
// Reads data/editorial/popular_used.yaml (WS3, generated by data/editorial/build_popular_used.py)
// and keeps only what the web shows: the order, each generation's id and its plain "why" line, and
// how many the landing shows (`method.landing_count`). Order and contents stay data, not code.
// A Docker build context has no data/editorial/: then the committed JSON is kept.
//
//   node scripts/popular-used.mjs           write the JSON (runs before `next build` and `next dev`)
//   node scripts/popular-used.mjs --check   fail if the committed JSON is out of date
/* global process, console */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import * as yaml from "js-yaml";

const here = path.dirname(fileURLToPath(import.meta.url));
export const IN_FILE = path.resolve(here, "../../../data/editorial/popular_used.yaml");
export const OUT_FILE = path.resolve(here, "../src/config/popular-used.generated.json");
const ID_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;

/** Validated, trimmed list. Throws on anything the landing can't use. */
export function buildPopularUsed(doc) {
  if (doc?.schema !== "editorial-popular-used/v1") throw new Error(`popular_used.yaml: unknown schema ${doc?.schema}`);
  const count = doc?.method?.landing_count;
  if (!Number.isInteger(count) || count < 1) throw new Error("popular_used.yaml: method.landing_count must be a whole number ≥ 1");
  const rows = Array.isArray(doc.generations) ? doc.generations : [];
  const seen = new Set();
  const generations = [...rows]
    .sort((a, b) => a.order - b.order)
    .map((g, i) => {
      const id = g?.generation_id;
      if (typeof id !== "string" || !ID_RE.test(id)) throw new Error(`popular_used.yaml: row ${i + 1} has no valid generation_id`);
      if (seen.has(id)) throw new Error(`popular_used.yaml: ${id} is listed twice`);
      seen.add(id);
      if (typeof g.why !== "string" || !g.why.trim()) throw new Error(`popular_used.yaml: ${id} has no 'why' line`);
      return { generation_id: id, why: g.why.trim() };
    });
  return {
    schema: "popular-used/v1",
    landing_count: count,
    licence: typeof doc.licence === "string" ? doc.licence : null,
    generations,
  };
}

function main() {
  const check = process.argv.includes("--check");
  const current = existsSync(OUT_FILE) ? readFileSync(OUT_FILE, "utf8") : "";
  if (!existsSync(IN_FILE)) {
    if (check) throw new Error(`${IN_FILE} not found`);
    console.warn(`popular-used: ${path.basename(IN_FILE)} not found, keeping ${path.basename(OUT_FILE)}`);
    return;
  }
  const json = `${JSON.stringify(buildPopularUsed(yaml.load(readFileSync(IN_FILE, "utf8"), { schema: yaml.CORE_SCHEMA })), null, 2)}\n`;
  if (check) {
    if (current !== json) {
      console.error(`popular-used: ${path.basename(OUT_FILE)} is stale; run node scripts/popular-used.mjs`);
      process.exit(1);
    }
    console.log("popular-used: up to date");
    return;
  }
  if (current !== json) writeFileSync(OUT_FILE, json);
  console.log(`popular-used: ${path.basename(OUT_FILE)} (landing shows ${json.match(/"landing_count": (\d+)/)?.[1]})`);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) main();
